node --input-type=module -e "
import { trash, remove, purgeExpired } from './src/trash.js';
const day = 24*60*60*1000;
const t = Date.now();
trash.push({ note: 'old', deletedAt: t - 31*day });
trash.push({ note: 'recent', deletedAt: t - 3*day });
remove({ title: 'fresh' });
console.log('after remove:', trash.map(e => e.note).join(','));
trash.length = 0;
trash.push({ note: 'old', deletedAt: t - 31*day });
trash.push({ note: 'recent', deletedAt: t - 3*day });
purgeExpired(t);
console.log('after purge:', trash.map(e => e.note).join(','));
"
